import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { login } from '../services/authService';

export default function Login() {
  const navigate = useNavigate();
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const onSubmit = async (e) => {
    e.preventDefault();
    if (loading) return;
    setError(null);
    setLoading(true);
    try {
      await login(username.trim(), password);
      navigate('/');
    } catch (err) {
      setError(err.message || 'Login failed');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{
      position: 'fixed',
      top: 0,
      left: 0,
      right: 0,
      bottom: 0,
      background: '#ffffff',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center'
    }}>
      <div className="container">
        <div className="row justify-content-center">
          <div className="col-12 col-md-10 col-lg-8">
            <div className="modern-card" style={{ boxShadow: '0 20px 60px rgba(0,0,0,.35)', border: '1px solid rgba(255,255,255,.06)' }}>
              <div className="row g-0">
                <div className="col-12 col-lg-6 p-4 d-flex flex-column justify-content-center" style={{ background: 'linear-gradient(140deg, #f0f9ff, #e0f2fe)' }}>
                  <div className="mb-3">
                    <span className="badge bg-primary bg-opacity-25 text-primary rounded-pill px-3 py-2">
                      <i className="bi bi-stars me-1"></i>
                      Welcome
                    </span>
                  </div>
                  <h2 className="mb-2" style={{ color: '#1f2937', fontSize: '1.75rem', fontWeight: '600' }}>FTM Garments Warehouse Carton Tracking System</h2>
                  <p className="mb-4" style={{ color: '#374151', fontSize: '1.1rem' }}>Modern, fast, and precise scanning for cartons, with real‑time PO validation and analytics.</p>
                  <div className="d-flex align-items-center gap-3 mb-2" style={{ fontSize: '2rem' }}>
                    <i className="bi bi-upc-scan" style={{ color: '#3b82f6' }}></i>
                    <i className="bi bi-qr-code-scan" style={{ color: '#10b981' }}></i>
                    <i className="bi bi-box-seam" style={{ color: '#f59e0b' }}></i>
                    <i className="bi bi-graph-up" style={{ color: '#ef4444' }}></i>
                  </div>
                  <small className="text-muted">Secure access required. Please sign in to continue.</small>
                </div>
                <div className="col-12 col-lg-6 p-4 bg-white" style={{ background: 'linear-gradient(180deg, #ffffff 0%, #f8fafc 100%)' }}>
                  <div className="mb-3">
                    <h5 className="mb-1">Sign in</h5>
                    <div className="text-muted small">Use your admin credentials to access the dashboard</div>
                  </div>
                  <form onSubmit={onSubmit}>
                    <div className="mb-3">
                      <label className="form-label-modern">Username or Email</label>
                      <div className="position-relative">
                        <i className="bi bi-person position-absolute" style={{ left: '12px', top: '50%', transform: 'translateY(-50%)', color: '#6b7280' }}></i>
                        <input
                          type="text"
                          className="form-control-modern ps-5"
                          value={username}
                          onChange={(e) => setUsername(e.target.value)}
                          autoComplete="username"
                          autoFocus
                        />
                      </div>
                    </div>
                    <div className="mb-3">
                      <label className="form-label-modern">Password</label>
                      <div className="position-relative">
                        <i className="bi bi-shield-lock position-absolute" style={{ left: '12px', top: '50%', transform: 'translateY(-50%)', color: '#6b7280' }}></i>
                        <input
                          type="password"
                          className="form-control-modern ps-5"
                          value={password}
                          onChange={(e) => setPassword(e.target.value)}
                          autoComplete="current-password"
                        />
                      </div>
                    </div>
                    {error && (
                      <div className="alert-modern alert-modern-danger mb-3">
                        <i className="bi bi-exclamation-triangle me-2"></i>{error}
                      </div>
                    )}
                    <div className="d-grid gap-2">
                      <button className="btn-modern btn-modern-primary py-2" type="submit" disabled={loading || !username || !password}>
                        {loading ? <><span className="spinner-border spinner-border-sm me-2"></span>Signing in...</> : <><i className="bi bi-box-arrow-in-right me-2"></i>Sign in</>}
                      </button>
                    </div>
                    <div className="text-center text-muted small mt-3">
                      <i className="bi bi-lock-fill me-1"></i> Your session is protected with secure cookies
                    </div>
                  </form>
                </div>
              </div>
            </div>
            <div className="text-center text-muted small mt-3">
              &copy; {new Date().getFullYear()} FTM Garments. All rights reserved.
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}


